                                                <span className={`text-[10px] font-black px-2 py-0.5 rounded-full ${badgeBg}`}>
                                                    {u.status}
                                                </span>
                                            </div>
                                            <p className="text-xs font-bold text-purple-700">{u.price}</p>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
