                                                onChange={() => toggleSelect(prop.id)}
                                                className="w-5 h-5 rounded accent-purple-600 cursor-pointer shadow"
                                            />
                                            <span className="bg-white/90 backdrop-blur text-gray-900 text-xs font-bold px-2.5 py-1 rounded-lg shadow-sm">
                                                {prop.type}
